// Component under test
@Component({
  standalone: true,
  template: `<p>{{ count() }}</p><button (click)="increment()">+</button>`
})
export class CounterComponent {
  count = signal(0);
  increment() { this.count.update(v => v + 1); }
}

// TestBed setup (Vitest / Jasmine syntax)
describe('CounterComponent', () => {
  let fixture: ComponentFixture<CounterComponent>;
  let component: CounterComponent;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [CounterComponent]   // standalone components go in imports
    }).compileComponents();

    fixture = TestBed.createComponent(CounterComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();  // initial render
  });

  it('starts at 0', () => {
    expect(fixture.nativeElement.querySelector('p').textContent).toBe('0');
  });

  it('increments on button click', () => {
    fixture.nativeElement.querySelector('button').click();
    fixture.detectChanges();  // required for OnPush and always good practice
    expect(component.count()).toBe(1);
    expect(fixture.nativeElement.querySelector('p').textContent).toBe('1');
  });
});

